package com.aghani.q20messenger;
import android.app.*;import android.content.*;import android.media.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=19,qualifiers="w400dp-h400dp-mdpi")
public class BackgroundAndNavigationTest {
 private android.content.Context context;private LocalStore store;
 @Before public void reset(){context=RuntimeEnvironment.getApplication();AppPrefs.save(context,"http://127.0.0.1:1","1000");AppPrefs.saveApiToken(context,"fixture-only");AppPrefs.setBackgroundEnabled(context,true);ReflectionHelpers.setStaticField(LocalStore.class,"instance",null);store=LocalStore.get(context);for(String table:new String[]{"messages","chats","sync_state","contact_names","call_history"})store.getWritableDatabase().delete(table,null,null);AppVisibility.visibleChat="";}
 @After public void clear(){AppVisibility.visibleChat="";}
 private JSONObject msg(int id,String jid,long time,boolean mine)throws Exception{return new JSONObject().put("_id",id).put("chat_jid",jid).put("chat_name","Alice").put("chat_type","chat").put("timestamp_ms",time).put("message","hello "+id).put("from_me",mine);}
 @Test public void listFocusDoesNotTintWholeContainer(){LinearLayout root=new LinearLayout(context);ListView list=new ListView(context);list.setClickable(true);root.addView(list);android.graphics.drawable.Drawable before=list.getBackground();HardwareNavigation.decorate(root);assertSame(before,list.getBackground());}
 public static class KeyRecorder extends Activity {final java.util.ArrayList<Integer> keys=new java.util.ArrayList<Integer>();@Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN)keys.add(event.getKeyCode());return true;}}
 @Test public void trackpadGestureKeepsVerticalAxisDespiteSidewaysJitter(){KeyRecorder activity=Robolectric.buildActivity(KeyRecorder.class).create().get();for(int i=0;i<6;i++){MotionEvent event=MotionEvent.obtain(0,100+i*80,MotionEvent.ACTION_MOVE,.25f,.8f,0);HardwareNavigation.trackball(activity,event);event.recycle();}MotionEvent jitter=MotionEvent.obtain(0,650,MotionEvent.ACTION_MOVE,1f,.1f,0);HardwareNavigation.trackball(activity,jitter);jitter.recycle();assertFalse(activity.keys.contains(KeyEvent.KEYCODE_DPAD_RIGHT));assertTrue(activity.keys.contains(KeyEvent.KEYCODE_DPAD_DOWN));MotionEvent horizontal=MotionEvent.obtain(0,1000,MotionEvent.ACTION_MOVE,.9f,0,0);HardwareNavigation.trackball(activity,horizontal);horizontal.recycle();assertTrue(activity.keys.contains(KeyEvent.KEYCODE_DPAD_RIGHT));}
 @Test public void localMessagesAppearBeforeBlockedNetworkCompletes()throws Exception {
  JSONObject message=msg(1,"a@c.us",System.currentTimeMillis(),false);store.upsertMessages(new JSONArray().put(message));ConversationCache.remember("a@c.us",store.getMessages("a@c.us",100,Long.MAX_VALUE));
  Intent intent=new Intent(context,ChatActivity.class).putExtra("peer_jid","a@c.us").putExtra("peer_name","Alice");ActivityController<ChatActivity> c=Robolectric.buildActivity(ChatActivity.class,intent).create();
  try{java.util.ArrayList<JSONObject> items=ReflectionHelpers.getField(c.get(),"messages");assertEquals(1,items.size());assertEquals("hello 1",items.get(0).getString("message"));}finally{c.destroy();}
 }
 @Test public void cachedPageInvalidatesWhenNewMessageArrives()throws Exception {
  store.upsertMessages(new JSONArray().put(msg(1,"a@c.us",100,false)));ConversationCache.remember("a@c.us",store.getMessages("a@c.us",100,Long.MAX_VALUE));assertNotNull(ConversationCache.messages("a@c.us"));store.upsertMessages(new JSONArray().put(msg(2,"a@c.us",200,false)));assertNull(ConversationCache.messages("a@c.us"));
 }
 @Test public void incomingCallHasPopupAndRespectsSilentMode()throws Exception {
  ((AudioManager)context.getSystemService(Context.AUDIO_SERVICE)).setRingerMode(AudioManager.RINGER_MODE_SILENT);ServiceController<IncomingCallService> c=Robolectric.buildService(IncomingCallService.class).create();
  try{IncomingCallService service=c.get();service.handleCall(new JSONObject("{active:true,incoming:true,call_id:'test-ring',peer:'a@c.us'}"));Notification notification=Shadows.shadowOf((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).getNotification(201);assertNotNull(notification);assertNotNull(notification.fullScreenIntent);assertNull(notification.sound);assertEquals(0,notification.defaults&Notification.DEFAULT_VIBRATE);Intent popup=Shadows.shadowOf(service).getNextStartedActivity();assertEquals(IncomingCallActivity.class.getName(),popup.getComponent().getClassName());service.handleCall(new JSONObject("{active:true,incoming:true,call_id:'test-ring',peer:'a@c.us'}"));assertNull(Shadows.shadowOf(service).getNextStartedActivity());service.handleCall(new JSONObject("{active:false,incoming:false}"));assertNull(Shadows.shadowOf((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).getNotification(201));}finally{c.destroy();}
 }
 @Test public void incomingPopupWaitsForAnswerInsteadOfAutoAccepting(){Intent intent=new Intent(context,IncomingCallActivity.class).putExtra("call_id","test-ring").putExtra("peer_jid","a@c.us").putExtra("peer_name","Alice");ActivityController<IncomingCallActivity> c=Robolectric.buildActivity(IncomingCallActivity.class,intent).create();try{assertNull(Shadows.shadowOf(c.get()).getNextStartedActivity());c.get().findViewById(android.R.id.button1).performClick();Intent call=Shadows.shadowOf(c.get()).getNextStartedActivity();assertEquals(CallActivity.class.getName(),call.getComponent().getClassName());assertTrue(call.getBooleanExtra("incoming",false));}finally{c.destroy();}}
 @Test public void notificationsExcludeOldHistoryOwnMessagesVisibleChatAndReadMessages()throws Exception {
  long now=System.currentTimeMillis();store.putState("notifications_since",now-1000);store.putState("notifications_after_id",0);((AudioManager)context.getSystemService(Context.AUDIO_SERVICE)).setRingerMode(AudioManager.RINGER_MODE_NORMAL);
  store.upsertMessages(new JSONArray().put(msg(1,"a@c.us",now,false)).put(msg(2,"own@c.us",now,true)).put(msg(3,"old@c.us",now-604800000,false)).put(msg(4,"visible@c.us",now,false)).put(msg(5,"read@c.us",now,false)));store.markChatRead("read@c.us");store.saveSyncCursor(5);AppVisibility.visibleChat="visible@c.us";MessageNotifications.afterSync(context);
  org.robolectric.shadows.ShadowNotificationManager manager=Shadows.shadowOf((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE));assertNotNull(manager.getNotification(MessageNotifications.id("a@c.us")));assertNotNull(manager.getNotification(MessageNotifications.id("a@c.us")).sound);for(String jid:new String[]{"own@c.us","old@c.us","visible@c.us","read@c.us"})assertNull(manager.getNotification(MessageNotifications.id(jid)));assertEquals(5,store.getState("notifications_after_id"));MessageNotifications.afterSync(context);assertEquals(1,manager.size());
 }
 @Test public void bootRestartsEnabledBackgroundListener(){new StartupReceiver().onReceive(context,new Intent(Intent.ACTION_BOOT_COMPLETED));Intent started=Shadows.shadowOf((android.app.Application)context).getNextStartedService();assertEquals(IncomingCallService.class.getName(),started.getComponent().getClassName());AppPrefs.setBackgroundEnabled(context,false);new StartupReceiver().onReceive(context,new Intent(Intent.ACTION_BOOT_COMPLETED));assertNull(Shadows.shadowOf((android.app.Application)context).getNextStartedService());}
}
